import json, os
logdir = 'logdir/exp_058_frozen_dt_emb_cheetah_s1'
os.chdir('/root/autodl-tmp/event-gated-adaptive-horizon')
for root, dirs, files in os.walk(logdir):
    for f in files:
        if f == 'metrics.jsonl':
            path = os.path.join(root, f)
            with open(path) as fh:
                lines = fh.readlines()
            for line in lines:
                d = json.loads(line)
                step = d.get('step', 0)
                ve = None
                for k in ['civo/ve_ratio', 've_ratio', 'civo/nve']:
                    if k in d:
                        ve = d[k]
                        break
                ret = None
                for k in ['eval/return', 'episode/return']:
                    if k in d:
                        ret = d[k]
                        break
                if ve is not None or ret is not None:
                    print(f'step={step}, ve_ratio={ve}, eval_return={ret}')
            last = json.loads(lines[-1])
            print(f'CURRENT_STEP={last.get(\"step\",\"?\")}')
            break
    else:
        print('No metrics.jsonl found yet')
